    private val supplementalUniversal = mapOf(
        "app_title" to "Focused Mind",
        "app_title_upper" to "FOCUSED MIND",
        "locked_symbol" to "🔒",
        "unlocked_symbol" to "✓"
    )

    private val universalFallback = translations.getValue("en")

    fun text(context: Context, key: String): String {
        val requested = LanguageManager.effectiveLocale(context).toLanguageTag()
        val exact = translations[requested] ?: emptyMap()
        val base = translations[requested.substringBefore('-')] ?: emptyMap()
        val extra = supplemental[requested] ?: supplemental[requested.substringBefore('-')] ?: emptyMap()
        return exact[key] ?: base[key] ?: extra[key] ?: supplementalUniversal[key] ?: universalFallback[key] ?: when (key) { "minimum_lead_required" -> "Choose a time at least 10 minutes from now." else -> key }
    }

    fun category(context: Context, id: Int): String {
        val lang = LanguageManager.effectiveLocale(context).language
        return when (id) {
            1 -> when (lang) { "pt" -> "Decisões Cruciais"; "es" -> "Decisiones Cruciales"; "fr" -> "Décisions cruciales"; "de" -> "Entscheidungen"; "it" -> "Decisioni cruciali"; "ja" -> "重要な決断"; "ko" -> "중요한 결정"; "ru" -> "Ключевые решения"; "pl" -> "Kluczowe decyzje"; "tr" -> "Kritik kararlar"; "ar" -> "قرارات مهمة"; "ms" -> "Keputusan penting"; "zh" -> "关键决定"; else -> "Crucial Decisions" }
            2 -> when (lang) { "pt" -> "Trabalho e Responsabilidades"; "es" -> "Trabajo y Responsabilidades"; "fr" -> "Travail et responsabilités"; "de" -> "Arbeit und Pflichten"; "it" -> "Lavoro e responsabilità"; "ja" -> "仕事と責任"; "ko" -> "업무와 책임"; "ru" -> "Работа и обязанности"; "pl" -> "Praca i obowiązki"; "tr" -> "İş ve sorumluluklar"; "ar" -> "العمل والواجبات"; "ms" -> "Kerja dan tanggungjawab"; "zh" -> "工作与职责"; else -> "Work & Responsibilities" }
            3 -> when (lang) { "pt" -> "Reflexões e Conexões"; "es" -> "Reflexiones y Conexiones"; "fr" -> "Réflexions et liens"; "de" -> "Reflexionen und Verbindungen"; "it" -> "Riflessioni e connessioni"; "ja" -> "振り返りとつながり"; "ko" -> "성찰과 연결"; "ru" -> "Размышления и связи"; "pl" -> "Refleksje i relacje"; "tr" -> "Düşünceler ve bağlantılar"; "ar" -> "التأملات والعلاقات"; "ms" -> "Refleksi dan hubungan"; "zh" -> "反思与连接"; else -> "Reflections & Connections" }
            4 -> text(context, "important_events")
            else -> text(context, "academic_focus")
