    fun day(context: Context, calendarDay: Int): String {
        val lang = LanguageManager.effectiveLocale(context).language
        val values = when (lang) {
            "pt" -> listOf("domingo", "segunda", "terça", "quarta", "quinta", "sexta", "sábado")
            "es" -> listOf("domingo", "lunes", "martes", "miércoles", "jueves", "viernes", "sábado")
